<main class="main"><div class="main__inner"><div class="portal-page"><header class="portal-page__header"><div><span class="module-eyebrow">Learning resources</span><h1>Class Notes</h1><p>Published notes for <?=e($student['class_name'])?>.</p></div></header><div class="portal-resource-grid">
<?php if(!$notes):?><section class="module-card"><div class="compact-empty"><h2>No notes published</h2><p>Your teacher's published notes will appear here.</p></div></section>
<?php else:foreach($notes as$n):?><article class="module-card"><div class="module-card__body"><span class="status-badge"><?=e($n['subject'])?></span><h2><?=e($n['title'])?></h2><p><?=e($n['chapter']?:'General topic')?> · <?=e($n['publish_date'])?></p><?php if($n['description']):?><p><?=nl2br(e($n['description']))?></p><?php endif?><div class="filter-actions"><?php if($n['attachment_path']):?><a class="btn btn--secondary" href="<?=url('/attachments/notes/'.$n['id'])?>" target="_blank" rel="noopener"><i data-lucide="eye"></i>Open file</a><?php endif?><?php if($n['external_url']):?><a class="btn btn--primary" href="<?=e($n['external_url'])?>" target="_blank" rel="noopener noreferrer"><i data-lucide="external-link"></i>Open link</a><?php endif?></div></div></article><?php endforeach;endif?></div></div></div></main>
